package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;

/**
 * A strategy is priced at the latest complete time it demonstrated for a query, not at the average or minimum of its
 * runs.
 * <p>
 * The reported symptom is a query that runs fast under the Janino-compiled parallel aggregate kernel and then settles
 * on {@code packedFtreeAggregate}, roughly 2x slower, for good. The cause is that {@link LmdbNativeCostPosteriorStore}
 * models a smoothed central estimate of log runtime, so a new 20-50% winner can be clipped toward its older runs
 * instead of becoming the next dispatch choice.
 * <p>
 * The rule these tests pin is symmetric: every complete normal run is believed immediately, whether it is faster or
 * slower than the previous one. A directly measured arm must not quarantine itself against its deliberately narrow
 * latest-run price before that new completion can replace the old price.
 */
class LmdbNativeLatestObservedPricingTest {

	private static final String COMPILED = LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_PARALLEL;
	private static final String PACKED = LmdbNativeAttemptMetrics.PATH_PACKED_FTREE_AGGREGATE;

	private static final long FAST_NANOS = 100_000_000L;
	private static final long SLOW_NANOS = 300_000_000L;

	private record Fixture(LmdbNativeStoreCostModel store, LmdbNativeAdaptiveCostModel model) {
	}

	/**
	 * A private store and a private machine model. Keeping the machine model private (rather than the JVM-wide one) and
	 * every test under its {@code MINIMUM_ADAPTIVE_SAMPLES} of 32 holds every arm in the DIRECT lane, where the
	 * posterior models log runtime itself and {@code logBase} is zero — which is what makes the arithmetic below
	 * reproducible.
	 */
	private static Fixture fixture() {
		LmdbNativeStoreCostModel store = new LmdbNativeStoreCostModel();
		LmdbNativeAdaptiveCostModel model = new LmdbNativeAdaptiveCostModel(new LmdbNativeMachineCostModel(), store,
				new LmdbNativeAdaptiveCostModel.Configuration(true, true));
		return new Fixture(store, model);
	}

	private static LmdbNativeCostEstimate estimate(String family) {
		LmdbNativePhysicalVariantKey key = LmdbNativePhysicalVariantKey.builder(family)
				.physicalOrderAndProperties(family)
				.build();
		LmdbNativeCostVector vector = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.SCANNED_ROW, 1_000);
		return new LmdbNativeCostEstimate(key, LmdbNativeCostVector.zero(), vector, 1_000, 0.1);
	}

	/**
	 * One execution recorded through the same door dispatch uses — the observation, not the model — because the role of
	 * the run is exactly what decides whether its elapsed may become the current price, and only the observation knows
	 * it. The clock is scripted so the measured elapsed is the value under test rather than the test's own wall time.
	 */
	private static void run(LmdbNativeAdaptiveCostModel model, LmdbNativeCostEstimate estimate, long elapsedNanos,
			LmdbNativeCostObservation.Role role) {
		long[] ticks = { 0L, elapsedNanos };
		AtomicInteger tick = new AtomicInteger();
		LmdbNativeCostObservation observation = new LmdbNativeCostObservation(estimate, model,
				() -> ticks[Math.min(tick.getAndIncrement(), ticks.length - 1)], role);
		observation.exhausted();
	}

	private static void runNormally(LmdbNativeAdaptiveCostModel model, LmdbNativeCostEstimate estimate,
			long elapsedNanos) {
		run(model, estimate, elapsedNanos, LmdbNativeCostObservation.Role.NORMAL);
	}

	/**
	 * The actionable price is the latest complete run, not a smoothed mean and not a historical minimum. A strategy
	 * that just ran faster must win the next dispatch; if its next complete run is slower, that new observation must be
	 * believed just as promptly so another strategy can beat it.
	 */
	@Test
	void latestCompletedTimeBecomesThePriceEvenWhenItIsSlower() {
		Fixture fixture = fixture();
		LmdbNativeCostEstimate arm = estimate(COMPILED);

		runNormally(fixture.model(), arm, SLOW_NANOS);
		runNormally(fixture.model(), arm, SLOW_NANOS);
		runNormally(fixture.model(), arm, FAST_NANOS);
		runNormally(fixture.model(), arm, SLOW_NANOS);

		assertEquals(SLOW_NANOS, fixture.model().predict(arm).expectedNanos(), SLOW_NANOS * 0.01,
				"the latest full run is the strategy's current cost, even when an older run was faster");
	}

	/**
	 * The regression itself. The compiled arm was the <em>slower</em> of the two — 400 ms against the packed f-tree's
	 * steady 200 ms — but its latest run answered in 100 ms. Averaged, it is a loser. Priced at its latest observation,
	 * it is the next winner.
	 */
	@Test
	void aTwiceAsFastMeasuredArmDisplacesTheIncumbent() {
		Fixture fixture = fixture();
		LmdbNativeCostEstimate compiled = estimate(COMPILED);
		LmdbNativeCostEstimate packed = estimate(PACKED);

		for (int i = 0; i < 4; i++) {
			runNormally(fixture.model(), packed, 200_000_000L);
			runNormally(fixture.model(), compiled, 400_000_000L);
		}
		runNormally(fixture.model(), compiled, 100_000_000L);

		assertTrue(
				LmdbNativeCostPrediction.displaces(fixture.model().predict(compiled),
						fixture.model().predict(packed), LmdbNativeAdaptiveArbitration.DEFAULT_LOG_GAMMA),
				"an arm whose latest complete run is twice as fast as the incumbent's latest must displace it; "
						+ "a 99% test over smoothed means demands roughly an elevenfold gap and never fires");
	}

	/**
	 * A directly measured price has deliberately minimal epistemic variance. A slower next completion must be allowed
	 * to replace it without first quarantining the arm against its previous narrow interval.
	 */
	@Test
	void aSlowerLatestRunRaisesPriceWithoutSevereMissQuarantine() {
		Fixture fixture = fixture();
		LmdbNativeCostEstimate arm = estimate(COMPILED);

		for (int i = 0; i < 8; i++) {
			runNormally(fixture.model(), arm, FAST_NANOS);
		}
		runNormally(fixture.model(), arm, FAST_NANOS * 50);

		assertFalse(
				fixture.store()
						.probeScheduler()
						.quarantined(arm.variantKey(), fixture.model().currentRegime(),
								fixture.store().regimeTracker().epoch()),
				"a complete run replaces a directly measured price and must not quarantine the arm first");
		assertEquals(FAST_NANOS * 50, fixture.model().predict(arm).expectedNanos(), FAST_NANOS * 0.01,
				"the slower latest completion becomes the current price immediately");
	}

	/**
	 * A bounded probe drains into a private 4096-row buffer under a deadline, so its elapsed measures a truncated run
	 * of a different shape. Recording one as the current price would describe work the arm never delivered to the real
	 * consumer. A normal run at the identical elapsed does become the price — the exclusion is about the role, not the
	 * number.
	 */
	@Test
	void probeCompletionsDoNotSetPriceButNormalRunsAtTheSameSpeedDo() {
		Fixture fixture = fixture();
		LmdbNativeCostEstimate arm = estimate(COMPILED);
		for (int i = 0; i < 4; i++) {
			runNormally(fixture.model(), arm, SLOW_NANOS);
		}

		run(fixture.model(), arm, FAST_NANOS, LmdbNativeCostObservation.Role.PROBE);
		double afterProbe = fixture.model().predict(arm).expectedNanos();

		runNormally(fixture.model(), arm, FAST_NANOS);
		double afterNormalRun = fixture.model().predict(arm).expectedNanos();

		// Stated as a comparison rather than an absolute bound: a probe still trains the posterior, so its elapsed
		// legitimately moves the posterior price some way down. What it must not do is set the latest-run price.
		assertTrue(afterProbe > afterNormalRun * 1.5,
				"a probe's buffered elapsed is not a full execution of the query and must not become the price; "
						+ "afterProbe=" + afterProbe + " afterNormalRun=" + afterNormalRun);
		assertEquals(FAST_NANOS, afterNormalRun, FAST_NANOS * 0.01,
				"the same elapsed measured by a full non-probe run is exactly the current price");
	}

	/**
	 * End to end through the dispatch policy, arranged so the ladder and the measurements disagree: the arm the ladder
	 * prefers ({@code irAggregateParallel}, which now heads the aggregate tier) is the <em>slower</em> one. If this
	 * passed only because of the reorder it would prove nothing, so the reorder is pointed the wrong way on purpose.
	 * <p>
	 * Three phases: a latest measurement overrules preference; a later slow run hands the choice to the now-faster
	 * rival; and a still-faster completion of that rival keeps it there.
	 */
	@Test
	void latestCompletedWinnerSurvivesUntilAnotherLatestRunBeatsIt() {
		Fixture fixture = fixture();
		LmdbNativeCostEstimate compiled = estimate(COMPILED);
		LmdbNativeCostEstimate packed = estimate(PACKED);
		List<LmdbNativeAdaptiveArbitration.Candidate<String>> offered = List.of(candidate(compiled, COMPILED),
				candidate(packed, PACKED));

		// Six runs each: past CONFIRMATION_FLOOR, so neither arm still owes a mandatory must-try trial that would
		// decide the dispatch for reasons other than the one under test.
		for (int i = 0; i < 6; i++) {
			runNormally(fixture.model(), compiled, 200_000_000L);
			runNormally(fixture.model(), packed, 100_000_000L);
		}

		assertEquals(PACKED, chosenFamily(fixture.model(), offered),
				"the packed f-tree's latest run took half the compiled arm's latest time; measured evidence must "
						+ "overrule the ladder");

		runNormally(fixture.model(), packed, 900_000_000L);

		assertEquals(COMPILED, chosenFamily(fixture.model(), offered),
				"once the packed arm's latest run is slower, the compiled arm's known-fast fallback becomes preferred");

		runNormally(fixture.model(), compiled, 50_000_000L);

		assertEquals(COMPILED, chosenFamily(fixture.model(), offered),
				"the compiled arm remains preferred after its latest run improves again");
	}

	private static LmdbNativeAdaptiveArbitration.Candidate<String> candidate(LmdbNativeCostEstimate estimate,
			String tag) {
		return new LmdbNativeAdaptiveArbitration.Candidate<>(estimate, LmdbNativeStrategyPreference.rank(tag),
				observation -> tag);
	}

	private static String chosenFamily(LmdbNativeAdaptiveCostModel model,
			List<LmdbNativeAdaptiveArbitration.Candidate<String>> offered) {
		LmdbNativeAdaptiveArbitration.DispatchPlan<String> plan = LmdbNativeAdaptiveArbitration.choose(offered, model,
				LmdbNativeAdaptiveArbitration.ProbeContext.disabled());
		assertTrue(plan instanceof LmdbNativeAdaptiveArbitration.DispatchPlan.Normal,
				"probing and hedging are disabled at this site, so the plan must be a plain dispatch: " + plan);
		return ((LmdbNativeAdaptiveArbitration.DispatchPlan.Normal<String>) plan).candidate()
				.estimate()
				.variantKey()
				.strategyFamily();
	}
}
